final class ImageGenerationExecutionTest extends WP_UnitTestCase {
 use PhotoWorkflowFixtureIsolation {tearDown as private restoreImageFixture;}
 private array $extraFloors=[];
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();global $wpdb;foreach(['ai_models','ai_tasks','integrations','integration_secrets']as $method){$t=DigiForge\Database\Tables::{$method}();$this->extraFloors[$t]=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0) FROM '.$t);}wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_ai','manage_digiforge_pod','manage_digiforge_research']);DigiForge\Core\Settings::protectProduction();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');}
 protected function tearDown():void {global $wpdb;foreach(array_reverse($this->extraFloors,true)as $t=>$floor)$wpdb->query('DELETE FROM '.$t.' WHERE id>'.(int)$floor);$this->restoreImageFixture();}
 private function policy():array {
  $ai=new DigiForge\AI\Repository();$task=$ai->createTask(['task_key'=>'image-'.wp_generate_uuid4(),'name'=>'Synthetic image task','environment'=>'production','required_capabilities'=>['image_generation']]);self::assertNotWPError($task);$model=$ai->createModel(['model_key'=>'image-'.wp_generate_uuid4(),'provider'=>'openai','environment'=>'production','model_class'=>'image','capabilities'=>['image_generation'],'enabled'=>true]);self::assertNotWPError($model);$integrations=new DigiForge\Integrations\Repository();$connection=$integrations->create(['provider'=>'ai','environment'=>'production','connection_key'=>'image-'.wp_generate_uuid4(),'display_name'=>'SYNTHETIC IMAGE CONNECTOR','status'=>'CONFIGURED','enabled'=>true,'config'=>[]]);self::assertNotWPError($connection);self::assertNotWPError($integrations->storeSecret((int)$connection['id'],'api_key','SYNTHETIC-NOT-A-PROVIDER-CREDENTIAL-'.wp_generate_uuid4()));
  $binding=['task_id'=>(int)$task['id'],'provider_models'=>[(int)$model['id']=>'gpt-image-1']];$r=(new ImageGenerationPolicyRepository())->review(['policy_key'=>'image-'.wp_generate_uuid4(),'version'=>'v1','binding'=>$binding,'integration_id'=>(int)$connection['id'],'size'=>'1024x1024','quality'=>'low','maximum_task_charge'=>'0.020000','currency'=>'USD','timeout_seconds'=>20,'max_output_bytes'=>2097152,'engines'=>['ORIGINAL_ARTWORK','PET_PORTRAIT','WATERCOLOR','LINE_ART','VINTAGE_PORTRAIT','AI_TRANSFORM'],'prompt_version'=>'v1','terms_source_sha256'=>hash('sha256','SYNTHETIC TERMS FOR TEST ONLY')]);self::assertNotWPError($r);self::assertFalse($r['policy']['enabled']);self::assertNotWPError((new ShopAiGovernanceRepository())->savePolicy(['shop_key'=>'personalized_pod','currency'=>'USD','budgets'=>['run'=>'0.020000','day'=>'0.040000','month'=>'0.100000'],'stages'=>['render'=>['limit'=>10,'monthly_budget'=>'0.100000','task_binding'=>$binding]]]));global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');return $r;
 }
 private function spec():array {return (new ReflectionMethod(DesignFactoryWorkflowTest::class,'prepared'))->invoke(new DesignFactoryWorkflowTest());}
 private function transport(int $status=200,bool $badPng=false):OfflineImageTransport {$png=DigiForge\POD\RasterArtworkCodec::encode(1024,1024,str_repeat("\x40\x80\xa0\xff",1024*1024));$body=json_encode(['created'=>time(),'data'=>[['b64_json'=>base64_encode($badPng?'bad png':$png)]],'usage'=>['input_tokens'=>10,'output_tokens'=>5,'total_tokens'=>15,'input_tokens_details'=>['text_tokens'=>4,'image_tokens'=>6]]]);return new OfflineImageTransport(['response'=>['code'=>$status],'headers'=>['x-request-id'=>'req_synthetic_'.str_replace('-','',wp_generate_uuid4())],'body'=>$body]);}
 private function quote(array $job,string $amount='0.020000'):void {$c=$job['identity']['wire_contract'];self::assertNotWPError((new MonetaryReservationRepository())->reviewQuote('personalized_pod',json_encode(['provider'=>'openai','quote_id'=>'synthetic-'.wp_generate_uuid4(),'model'=>$c['model'],'request_sha256'=>$c['request_sha256'],'currency'=>'USD','maximum_charge'=>$amount,'inclusive_all_charges'=>true,'valid_from'=>gmdate('Y-m-d\TH:i:s\Z',time()-10),'valid_until'=>gmdate('Y-m-d\TH:i:s\Z',time()+3600),'evidence_kind'=>'SYNTHETIC_TEST_ONLY']),'CONFIRM_PROVIDER_QUOTE'));}
 public function testRealRequestPipelineUsesInclusiveReservationAndImmutableRasterThenManualDerivative():void {
  self::assertTrue(class_exists(ImageGenerationExecution::class),'Executable governed image dispatch service missing.');$policy=$this->policy();$spec=$this->spec();$transport=$this->transport();$s=new ImageGenerationExecution($transport);$run=['run_id'=>'image-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')];$job=$s->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],$run);self::assertNotWPError($job);$this->quote($job);$done=$s->run('personalized_pod',$job['id']);self::assertNotWPError($done,is_wp_error($done)?$done->get_error_code().' '.json_encode($s->read('personalized_pod',$job['id'])['error_class']??null):'');self::assertSame('SUCCEEDED',$done['state']);self::assertSame(1,$transport->calls());self::assertSame('OFFLINE_SIMULATOR',$done['identity']['mode']);self::assertGreaterThan(0,$done['usage_id']);self::assertFalse($done['result']['editable_vector']);$artifact=$s->artifact('personalized_pod',$job['id']);self::assertNotWPError($artifact);self::assertSame($done['result']['sha256'],hash('sha256',$artifact['bytes']));self::assertWPError($s->run('personalized_pod',$job['id']));self::assertSame(1,$transport->calls());
  $payload=['svg'=>file_get_contents(__DIR__.'/../fixtures/design-factory/mug-original.svg'),'raster_uploads'=>[],'rights_note'=>'Synthetic human editable derivative; no commercial approval','source_note'=>'Manual vector adaptation test'];$linked=$s->linkDerivative('personalized_pod',$job['id'],$done['result']['sha256'],$payload,true);self::assertNotWPError($linked);self::assertSame('DERIVATIVE_LINKED',$linked['state']);$v=(new DigiForge\Research\DesignFactoryRepository())->read('personalized_pod',$linked['derivative_hash']);self::assertNotWPError($v);self::assertSame('ASSET_READY',$v['record']['kind']);self::assertNull($v['review_state']);self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public function testExhaustedRunMissingQuoteCancellationAndNetworkLocksDispatchNothing():void {
  self::assertTrue(class_exists(ImageGenerationExecution::class));$policy=$this->policy();$spec=$this->spec();$t=$this->transport();$s=new ImageGenerationExecution($t);$run=['run_id'=>'image-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')];$job=$s->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],$run);self::assertNotWPError($job);self::assertWPError($s->run('personalized_pod',$job['id']));self::assertSame(0,$t->calls());$this->quote($job);$completed=$s->run('personalized_pod',$job['id']);self::assertNotWPError($completed,is_wp_error($completed)?$completed->get_error_code().' '.json_encode($s->read('personalized_pod',$job['id'])['error_class']??null):'');$new=$s->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],$run+['unused'=>'reject']);self::assertWPError($new);$second=$s->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],['run_id'=>$run['run_id'],'started_at'=>$run['started_at']],$job['id']);self::assertNotWPError($second);self::assertWPError($s->run('personalized_pod',$second['id']));self::assertSame(1,$t->calls());self::assertNotWPError($s->cancel('personalized_pod',$second['id']));self::assertWPError($s->run('personalized_pod',$second['id']));
  $live=new ImageGenerationExecution();$network=$live->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],['run_id'=>'network-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]);self::assertNotWPError($network);$calls=0;$block=function($pre)use(&$calls){$calls++;return new WP_Error('forbidden');};add_filter('pre_http_request',$block,PHP_INT_MAX);try{self::assertWPError($live->run('personalized_pod',$network['id']));}finally{remove_filter('pre_http_request',$block,PHP_INT_MAX);}self::assertSame(0,$calls);
 }
 public function testMalformedChargedOutputAndInterruptedDispatchRemainHeldWithoutRetry():void {
  self::assertTrue(class_exists(ImageGenerationExecution::class));$policy=$this->policy();$spec=$this->spec();$t=$this->transport(200,true);$s=new ImageGenerationExecution($t);$job=$s->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],['run_id'=>'image-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]);self::assertNotWPError($job);$this->quote($job);self::assertWPError($s->run('personalized_pod',$job['id']));$held=$s->read('personalized_pod',$job['id']);self::assertNotWPError($held);self::assertSame('UNKNOWN',$held['state']);self::assertGreaterThan(0,$held['usage_id']);self::assertWPError($s->run('personalized_pod',$job['id']));self::assertSame(1,$t->calls());
 }
 public function testPublicSenderRejectsBodyAndEndpointSubstitutionBeforeClaim():void {
  $policy=$this->policy();$spec=$this->spec();$transport=$this->transport();$service=new ImageGenerationExecution($transport);$job=$service->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],['run_id'=>'wire-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]);self::assertNotWPError($job);$this->quote($job);
  $money=new MonetaryReservationRepository();$quote=$money->findQuote('personalized_pod',$job['identity']['wire_contract']);self::assertNotWPError($quote);$usage=(new ShopAiGovernanceRepository())->reserveGeneration('personalized_pod','render','image-'.$job['id'],$job['identity']['run_context'],$quote);self::assertNotWPError($usage);$journal=new DigiForge\AI\ImageGenerationJournal();$job=$journal->append($job['id'],$job['event_sha256'],['state'=>'RESERVED','usage_id'=>(int)$usage['id']]);self::assertNotWPError($job);$job=$journal->append($job['id'],$job['event_sha256'],['state'=>'DISPATCHING']);self::assertNotWPError($job);
  $wire=DigiForge\AI\ImageGenerationWireContract::request('gpt-image-1',$job['identity']['prompt'],'1024x1024','low',null);$bad=$wire;$bad['body']='{"model":"changed","prompt":"substitution"}';$bad['body_sha256']=hash('sha256',$bad['body']);$client=new DigiForge\AI\ImageGenerationHttpClient();self::assertWPError($client->send($job['id'],$bad,$transport),'Body substitution with unchanged request identity must not dispatch.');self::assertSame(0,$transport->calls());$bad=$wire;$bad['url']='https://attacker.example.invalid/collect';self::assertWPError($client->send($job['id'],$bad,$transport));self::assertSame(0,$transport->calls());self::assertNotWPError($client->send($job['id'],$wire,$transport));self::assertSame(1,$transport->calls());
  global $wpdb;$wpdb->delete($wpdb->options,['option_name'=>'df_shop2_image_send_'.$job['id']]);self::assertWPError($client->send($job['id'],$wire,$transport),'Surviving audit must fence deletion of the one-use option.');self::assertSame(1,$transport->calls());
 }

 public function testRevokedResearchCannotReadGeneratedDesignJobs():void {
