 public function testRecoveryDoesNotRaceAnActiveDispatchLease():void {
  $policy=$this->policy();$spec=$this->spec();$s=new ImageGenerationExecution($this->transport());$job=$s->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],['run_id'=>'recovery-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]);self::assertNotWPError($job);$j=new DigiForge\AI\ImageGenerationJournal();$job=$j->append($job['id'],$job['event_sha256'],['state'=>'RESERVED','usage_id'=>123456]);self::assertNotWPError($job);$job=$j->append($job['id'],$job['event_sha256'],['state'=>'DISPATCHING']);self::assertNotWPError($job);$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$lock=DigiForge\AI\ImageGenerationHttpClient::lockName($job['id']);self::assertSame('1',(string)$other->get_var($other->prepare('SELECT GET_LOCK(%s,0)',$lock)));try{self::assertWPError($s->recover('personalized_pod',$job['id']),'Recovery must not classify an active worker as interrupted.');self::assertSame('DISPATCHING',$s->read('personalized_pod',$job['id'])['state']);}finally{$other->get_var($other->prepare('SELECT RELEASE_LOCK(%s)',$lock));$other->close();}self::assertSame('UNKNOWN',$s->recover('personalized_pod',$job['id'])['state']);self::assertWPError($s->run('personalized_pod',$job['id']));
 }

 public function testArtisticRequestHonorsFrozenSourceResourceBoundsBeforeDispatch():void {
  $helper=new FiveEngineArchitectureTest();[$request,$path,$rights]=(new ReflectionMethod(FiveEngineArchitectureTest::class,'fixture'))->invoke($helper,'PET_PORTRAIT');try{$w=new DigiForge\POD\TransformationWorkflow();$key=wp_generate_uuid4();self::assertNotWPError($w->create('personalized_pod',$key,$request,$path,$rights));self::assertNotWPError($w->verifyInput('personalized_pod',$key));$policy=$this->policy();$s=new ImageGenerationExecution($this->transport());self::assertWPError($s->prepareTransformation('personalized_pod',$key,$policy['hash'],['run_id'=>'bounded-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]),'A 16-pixel source job must not authorize a 1-megapixel output or longer timeout.');}finally{unlink($path);}
 }

 public function testAllFiveArtisticEnginesUseTheGovernedEditPipelineWithoutProductionClaims():void {
  $policy=$this->policy();$helper=new FiveEngineArchitectureTest();$totalCalls=0;$w=new DigiForge\POD\TransformationWorkflow();
  foreach(DigiForge\POD\TransformationEngineContract::ENGINES as $engine){
   $transport=$this->transport();$s=new ImageGenerationExecution($transport);
   [$request,$path,$rights]=(new ReflectionMethod(FiveEngineArchitectureTest::class,'fixture'))->invoke($helper,$engine);try{
    $request['limits']=array_replace($request['limits'],['max_output_bytes'=>2097152,'max_pixels'=>1048576,'max_execution_seconds'=>20]);
    if($engine==='AI_TRANSFORM')self::assertNotWPError($w->registerMode('personalized_pod',(new ReflectionMethod(FiveEngineArchitectureTest::class,'syntheticMode'))->invoke($helper,$rights)));
    $key=wp_generate_uuid4();self::assertNotWPError($w->create('personalized_pod',$key,$request,$path,$rights));self::assertNotWPError($w->verifyInput('personalized_pod',$key));self::assertNotWPError((new ShopAiGovernanceRepository())->savePolicy(['shop_key'=>'personalized_pod','currency'=>'USD','budgets'=>['run'=>'0.020000','day'=>'0.200000','month'=>'0.200000'],'stages'=>['render'=>['limit'=>10,'monthly_budget'=>'0.200000','task_binding'=>$policy['policy']['binding']]]]));
    $job=$s->prepareTransformation('personalized_pod',$key,$policy['hash'],['run_id'=>'engine-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]);self::assertNotWPError($job);self::assertSame($engine,$job['identity']['engine']);self::assertSame(hash_file('sha256',$path),$job['identity']['wire_contract']['source_sha256']);self::assertSame('https://api.openai.com/v1/images/edits',$job['identity']['wire_contract']['url']);$this->quote($job);$done=$s->run('personalized_pod',$job['id']);self::assertNotWPError($done,is_wp_error($done)?$done->get_error_code():'');self::assertSame('SUCCEEDED',$done['state']);self::assertFalse($done['result']['editable_vector']);self::assertFalse($done['result']['supplier_certified']);self::assertSame('INPUT_VERIFIED',$w->read('personalized_pod',$key)['state'],'Raster candidate is not silently adopted as a licensed editable final artifact.');
   }finally{$totalCalls+=$transport->calls();unlink($path);}
  }self::assertSame(5,$totalCalls);
 }
