  $policy=$this->policy();$spec=$this->spec();$limits=['run'=>'0.100000','day'=>'0.100000','month'=>'0.100000'];if($period!=='task')$limits[$period]='0.010000';self::assertNotWPError((new ShopAiGovernanceRepository())->savePolicy(['shop_key'=>'personalized_pod','currency'=>'USD','budgets'=>$limits,'stages'=>['render'=>['limit'=>10,'monthly_budget'=>'0.100000','task_binding'=>$policy['policy']['binding']]]]));$t=$this->transport();$s=new ImageGenerationExecution($t);$job=$s->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],['run_id'=>'ceiling-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]);self::assertNotWPError($job);$this->quote($job,$amount);self::assertWPError($s->run('personalized_pod',$job['id']));self::assertSame(0,$t->calls());
 }
