 public function testUnconfirmedClaimCommitNeverDispatches():void {
  $policy=$this->policy();$spec=$this->spec();$transport=$this->transport();$s=new ImageGenerationExecution($transport);$job=$s->prepareDesign('personalized_pod',$spec['hash'],$policy['hash'],['run_id'=>'commit-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]);self::assertNotWPError($job);$this->quote($job);$money=new MonetaryReservationRepository();$quote=$money->findQuote('personalized_pod',$job['identity']['wire_contract']);self::assertNotWPError($quote);$usage=(new ShopAiGovernanceRepository())->reserveGeneration('personalized_pod','render','image-'.$job['id'],$job['identity']['run_context'],$quote);self::assertNotWPError($usage);$j=new DigiForge\AI\ImageGenerationJournal();$job=$j->append($job['id'],$job['event_sha256'],['state'=>'RESERVED','usage_id'=>(int)$usage['id']]);self::assertNotWPError($job);$job=$j->append($job['id'],$job['event_sha256'],['state'=>'DISPATCHING']);self::assertNotWPError($job);$wire=DigiForge\AI\ImageGenerationWireContract::request('gpt-image-1',$job['identity']['prompt'],'1024x1024','low',null);
  $claim=false;$fault=function(string $sql)use(&$claim):string{if(str_contains($sql,'INSERT INTO')&&str_contains($sql,'image_dispatch_claimed'))$claim=true;if($claim&&trim($sql)==='COMMIT')return 'SELECT 1';return $sql;};add_filter('query',$fault);try{self::assertWPError((new DigiForge\AI\ImageGenerationHttpClient())->send($job['id'],$wire,$transport),'Uncommitted local claim cannot authorize any dispatch.');self::assertSame(0,$transport->calls());}finally{remove_filter('query',$fault);global $wpdb;$wpdb->query('ROLLBACK');$wpdb->query('SET autocommit=1');}
 }

